package state_test

import (
	"regexp"
	"strconv"
	"strings"
	"testing"

	"github.com/TamasGorgics/recon-agent/internal/approval/state"
)

func TestMarkdownShape(t *testing.T) {
	doc := string(state.RenderMarkdown())

	for _, want := range []string{
		"Code generated by tools/state-machine-doc",
		"DO NOT EDIT",
		"go generate ./internal/approval/state",
		"# Proposal state machine",
		"| Status | Terminal | Meaning |",
		"| # | From | To | Actor | Reason | Purpose |",
		"## Version and CAS",
		"## Audit",
		"## Expiry",
		"## Terminal states",
		"## apply_failed retry caveat",
	} {
		if !strings.Contains(doc, want) {
			t.Errorf("rendered document is missing %q", want)
		}
	}

	for _, status := range state.AllStatuses() {
		if !strings.Contains(doc, "`"+string(status)+"`") {
			t.Errorf("rendered document is missing status %q", status)
		}
	}

	rows := 0
	for i, edge := range state.Edges() {
		row := "| " + strconv.Itoa(i+1) + " | `" + string(edge.From) + "` | `" +
			string(edge.To) + "` | `" + string(edge.Actor) + "` |"
		if !strings.Contains(doc, row) {
			t.Errorf("rendered document is missing edge row %q", row)
		}
	}
	for _, line := range strings.Split(doc, "\n") {
		if edgeRow.MatchString(line) {
			rows++
		}
	}
	if rows != 17 {
		t.Fatalf("rendered transition rows = %d, want 17", rows)
	}

	for _, terminal := range []state.Status{
		state.StatusApplied, state.StatusRejected, state.StatusExpired, state.StatusSuperseded,
	} {
		if !strings.Contains(doc, "| `"+string(terminal)+"` | yes |") {
			t.Errorf("rendered terminal table is missing %q", terminal)
		}
	}

	// No volatile data: no absolute path, timestamp, hash, or wall-clock call.
	if strings.Contains(doc, "/Users/") {
		t.Error("rendered document contains an absolute path")
	}
	if dateLike.MatchString(doc) {
		t.Error("rendered document contains a date-like timestamp")
	}
	if strings.Contains(doc, "time.Now") {
		t.Error("rendered document mentions time.Now")
	}
}

var (
	edgeRow  = regexp.MustCompile(`^\| [0-9]+ \|`)
	dateLike = regexp.MustCompile(`\b(19|20)[0-9]{2}-[0-9]{2}-[0-9]{2}\b`)
)
